 const h={a:d.ans},dist=km(la,lo,h.a[0],h.a[1]),sec=Math.round((Date.now()-d.t0)/1000),score=Math.round(1000*Math.exp(-dist/600))+Math.max(0,150-sec),j={score,d:dist,sec,xp:Math.min(50,Math.round(score/20))};
