const route=l=>{const r=byDate(l);if(!r.length)return'';const cities=r.map(c=>P[c.p][1]).filter((x,i,a)=>i==0||x!=a[i-1]),last=r[r.length-1];return`<h3>Parcours</h3><p style="margin:0 0 8px">${cities.map(x=>`<span class="tag">${x}</span>`).join(' → ')}</p><div class="ok">Dernier emplacement connu : <b>${P[last.p][1]}</b> · ${last.date}</div><button class="btn w" data-a="journey">Lancer le voyage</button>`};
